// vodServer serves the recorded two-segment stream that the HLS reader tests
// also use, so these checks run against real transport-stream segments rather
// than generated bytes.
func vodServer(t *testing.T) *httptest.Server {
	t.Helper()
	dir, err := filepath.Abs(filepath.Join("..", "hls", "testdata"))
	if err != nil {
		t.Fatalf("resolve fixtures: %v", err)
	}
	if _, err := os.Stat(filepath.Join(dir, "vod", "index.m3u8")); err != nil {
		t.Fatalf("fixture missing: %v", err)
	}
	server := httptest.NewServer(http.FileServer(http.Dir(dir)))
	t.Cleanup(server.Close)
	return server
}

// readPlaylist reads the fixture playlist through the same reader the app uses.
func readPlaylist(t *testing.T, address string) hls.Info {
	t.Helper()
	info, err := hls.Read(context.Background(), address, hls.Options{})
	if err != nil {
		t.Fatalf("read playlist: %v", err)
	}
	return info
}

func TestAddStoresPlayableSegments(t *testing.T) {
	server := vodServer(t)
	dir := t.TempDir()
	buffer, err := New(Options{Dir: dir})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")

	for _, segment := range info.Segments {
		stored, err := buffer.Add(context.Background(), server.Client(), segment)
		if err != nil {
			t.Fatalf("add segment %d: %v", segment.Sequence, err)
		}
		if stored.Bytes == 0 {
			t.Fatalf("segment %d stored no bytes", segment.Sequence)
		}
		if _, err := os.Stat(stored.Path); err != nil {
			t.Fatalf("segment %d not on disk: %v", segment.Sequence, err)
		}
		if stored.Bytes != int64(len(readFile(t, stored.Path))) {
			t.Fatalf("segment %d size does not match the file", segment.Sequence)
		}
	}

	ranges := buffer.Ranges()
	if len(ranges) != 1 {
		t.Fatalf("ranges = %v, want one", ranges)
	}
	if ranges[0].Start != 0 || ranges[0].End != 4*time.Second {
		t.Fatalf("range = %s..%s, want 0s..4s", ranges[0].Start, ranges[0].End)
	}
	if got := buffer.Bytes(); got <= 0 {
		t.Fatalf("buffer bytes = %d, want the two segment sizes", got)
	}
	if gaps := buffer.Gaps(); len(gaps) != 0 {
		t.Fatalf("gaps = %v, want none", gaps)
	}
	if available, ok := buffer.Available(); !ok || available.Start != 0 || available.End != 4*time.Second {
		t.Fatalf("available = %v, %v", available, ok)
	}
	if err := buffer.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
}

func readFile(t *testing.T, path string) []byte {
	t.Helper()
	body, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return body
}

func TestAddRejectsUnplayableSegment(t *testing.T) {
	server := vodServer(t)
	// An HTML error page with a 200 status is what a broken origin sometimes
	// returns; it must not be stored as media.
	broken := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html")
		_, _ = w.Write([]byte("<html><body>not found</body></html>"))
	}))
	t.Cleanup(broken.Close)

	dir := t.TempDir()
	buffer, err := New(Options{Dir: dir})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")

	if _, err := buffer.Add(context.Background(), server.Client(), info.Segments[0]); err != nil {
		t.Fatalf("add first segment: %v", err)
	}
	bad := info.Segments[1]
	bad.URI = broken.URL + "/seg_001.ts"
	_, err = buffer.Add(context.Background(), broken.Client(), bad)
	if !errors.Is(err, ErrNotPlayable) {
		t.Fatalf("add broken segment = %v, want ErrNotPlayable", err)
	}

	if segments := buffer.Segments(); len(segments) != 1 {
		t.Fatalf("stored %d segments, want only the playable one", len(segments))
	}
	gaps := buffer.Gaps()
	if len(gaps) != 1 {
		t.Fatalf("gaps = %v, want one", gaps)
	}
	if gaps[0].Start != 2*time.Second {
		t.Fatalf("gap starts at %s, want 2s", gaps[0].Start)
	}
	if gaps[0].KnownLength {
		t.Fatalf("gap claims a measured length without a follow-up segment: %s", gaps[0])
	}
	if _, err := buffer.Locate(3 * time.Second); !errors.Is(err, ErrNoRange) {
		t.Fatalf("locate inside the gap = %v, want ErrNoRange", err)
	}
}

func TestMissingSegmentSplitsRanges(t *testing.T) {
	server := vodServer(t)
	dir := t.TempDir()
	buffer, err := New(Options{Dir: dir})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")

	if _, err := buffer.Add(context.Background(), server.Client(), info.Segments[0]); err != nil {
		t.Fatalf("add first segment: %v", err)
	}
	// Skip the second listed segment, which is what a playlist that rolled past
	// it looks like: segment 1 is never downloaded, segment 2 is.
	skipped := info.Segments[1]
	skipped.Sequence = 2
	skipped.ProgramDateTime = skipped.ProgramDateTime.Add(2 * time.Second)
	skipped.URI = server.URL + "/vod/seg1.ts"
	if _, err := buffer.Add(context.Background(), server.Client(), skipped); err != nil {
		t.Fatalf("add later segment: %v", err)
	}

	gaps := buffer.Gaps()
	if len(gaps) != 1 {
		t.Fatalf("gaps = %v, want one", gaps)
	}
	if gaps[0].Start != 2*time.Second || gaps[0].End != 4*time.Second || !gaps[0].KnownLength {
		t.Fatalf("gap = %s, want 2s..4s measured", gaps[0])
	}
	ranges := buffer.Ranges()
	if len(ranges) != 2 {
		t.Fatalf("ranges = %v, want two", ranges)
	}
	if ranges[1].Start != 4*time.Second || ranges[1].End != 6*time.Second {
		t.Fatalf("second range = %s..%s, want 4s..6s", ranges[1].Start, ranges[1].End)
	}
	if _, err := buffer.Locate(3 * time.Second); !errors.Is(err, ErrNoRange) {
		t.Fatalf("locate inside the skipped media = %v, want ErrNoRange", err)
	}
	located, err := buffer.Locate(4*time.Second + 500*time.Millisecond)
	if err != nil {
		t.Fatalf("locate inside the second range: %v", err)
	}
	if located.Sequence != 2 {
		t.Fatalf("located segment %d, want 2", located.Sequence)
	}
}

func TestEvictKeepsProtectedSegments(t *testing.T) {
	server := vodServer(t)
	dir := t.TempDir()
	// A byte limit smaller than the first segment forces eviction on the second
	// add, without relying on retention time.
	buffer, err := New(Options{Dir: dir, MaxBytes: 1 << 10})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")
	var stored []Segment
	for _, segment := range info.Segments {
		one, err := buffer.Add(context.Background(), server.Client(), segment)
		if err != nil {
			t.Fatalf("add segment %d: %v", segment.Sequence, err)
		}
		stored = append(stored, one)
	}

	kept := map[int]bool{}
	removed := buffer.Evict(func(segment Segment) bool {
		keep := segment.Sequence == stored[len(stored)-1].Sequence
		kept[segment.Sequence] = keep
		return keep
	})
	if len(removed) != 1 || removed[0] != stored[0].Sequence {
		t.Fatalf("removed %v, want only segment %d", removed, stored[0].Sequence)
	}
	if _, err := os.Stat(stored[0].Path); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("evicted segment is still on disk: %v", err)
	}
	remaining := buffer.Segments()
	if len(remaining) != 1 || remaining[0].Sequence != stored[1].Sequence {
		t.Fatalf("remaining = %v, want the protected segment", remaining)
	}
	if buffer.Bytes() != remaining[0].Bytes {
		t.Fatalf("bytes = %d, want %d", buffer.Bytes(), remaining[0].Bytes)
	}
}

func TestCloseRemovesOwnedDirectory(t *testing.T) {
	root := t.TempDir()
	dir := filepath.Join(root, "cache")
	buffer, err := New(Options{Dir: dir})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	server := vodServer(t)
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")
	if _, err := buffer.Add(context.Background(), server.Client(), info.Segments[0]); err != nil {
		t.Fatalf("add segment: %v", err)
	}
	if err := buffer.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	if _, err := os.Stat(dir); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("cache directory survived close: %v", err)
	}
	if err := buffer.Close(); err != nil {
		t.Fatalf("second close: %v", err)
	}
	if _, err := buffer.Add(context.Background(), server.Client(), info.Segments[0]); !errors.Is(err, core.ErrClosed) {
		t.Fatalf("add after close = %v, want ErrClosed", err)
	}
}

func TestAddRejectsCredentialsInAddress(t *testing.T) {
	dir := t.TempDir()
	buffer, err := New(Options{Dir: dir})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	segment := hls.Segment{Sequence: 0, Duration: 2 * time.Second, URI: "https://user:secret@example.com/seg.ts"}
	_, err = buffer.Add(context.Background(), http.DefaultClient, segment)
	if !errors.Is(err, core.ErrCredentialsInURI) {
		t.Fatalf("add with credentials = %v, want ErrCredentialsInURI", err)
	}
	if gaps := buffer.Gaps(); len(gaps) != 1 {
		t.Fatalf("gaps = %v, want the refusal recorded", gaps)
	}
}

func TestSegmentNameCarriesNoAddress(t *testing.T) {
	server := vodServer(t)
	buffer, err := New(Options{Dir: t.TempDir()})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")
	stored, err := buffer.Add(context.Background(), server.Client(), info.Segments[0])
	if err != nil {
		t.Fatalf("add segment: %v", err)
	}
	if got := filepath.Base(stored.Path); got != "seg-00000000.ts" {
		t.Fatalf("stored file = %q, want the sequence-based name", got)
	}
}

// TestJoinStartsAtTheAskedSegment covers the recording the desktop opens for
// replay: the range that holds the asked time is written as one transport
// stream, and a start inside a segment begins at that segment because a
// segment cannot be cut.
func TestJoinStartsAtTheAskedSegment(t *testing.T) {
	server := vodServer(t)
	buffer, err := New(Options{Dir: t.TempDir()})
	if err != nil {
		t.Fatalf("new buffer: %v", err)
	}
	info := readPlaylist(t, server.URL+"/vod/index.m3u8")
	for _, segment := range info.Segments {
		if _, err := buffer.Add(context.Background(), server.Client(), segment); err != nil {
			t.Fatalf("add segment %d: %v", segment.Sequence, err)
		}
	}
	whole, err := buffer.Join(0)
	if err != nil {
		t.Fatalf("join: %v", err)
	}
	stored := buffer.Segments()
	want := int64(0)
	for _, segment := range stored {
		want += segment.Bytes
	}
	joined, err := os.ReadFile(whole)
	if err != nil {
		t.Fatalf("read recording: %v", err)
	}
	if int64(len(joined)) != want {
		t.Fatalf("recording is %d bytes, want the %d of both segments", len(joined), want)
	}
	if len(joined) == 0 || joined[0] != 0x47 {
		t.Fatalf("recording does not start with a transport stream sync byte")
	}
	late, err := buffer.Join(2500 * time.Millisecond)
	if err != nil {
		t.Fatalf("join later: %v", err)
	}
	if _, err := os.Stat(whole); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("the first recording survived the second one: %v", err)
	}
	lateBytes, err := os.ReadFile(late)
	if err != nil {
		t.Fatalf("read later recording: %v", err)
	}
	if len(lateBytes) >= len(joined) {
		t.Fatalf("a start at 2.5s keeps the finished segment: %d of %d bytes", len(lateBytes), len(joined))
	}
	if _, err := buffer.Join(9 * time.Second); !errors.Is(err, ErrNoRange) {
		t.Fatalf("join after the buffer = %v, want ErrNoRange", err)
	}
	if err := buffer.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
	if _, err := os.Stat(late); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("closing the buffer kept the recording: %v", err)
	}
	if _, err := buffer.Join(0); !errors.Is(err, core.ErrClosed) {
		t.Fatalf("join after close = %v, want ErrClosed", err)
	}
}
